/* cppi::1cbab092aed1d43f6d54504e9f6baa135c63f6196606f109b707d02ab7fa701f */
SELECT COUNT(*) FROM (SELECT * FROM (
select business_date, cppib_sec_id AS cppib_id,  from_currency_code AS from_currency, 
to_currency_code AS to_currency, type AS instrument_type, sub_type AS instrument_sub_type,
bid_value, askvalue AS ask_value, mid_value AS mid_value, business_date AS rate_date,
price_source_code AS price_source from market.cppib_rates
where business_date = date('2025-06-25') AND "type" = 'CURRENCY' AND sub_type = 'CROSS_RATE' AND price_source_code = 'WM Company'
) z_q WHERE from_currency IN ('CAD')
) dbvrcnt

/* cppi::a54bef7f73d291431f71264af7614ee2ae667e1f180d9bcb5548cb3673b63f55 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-26' and business_date <= date '2025-06-26' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

/* cppi::7e302d73a6c6c0c552a02c81beb987e814c58f0ce4301734b7753cfa87806fbb */
select cusip, isin, ticker as issuer_code, issuer_name,coupon_rate as coupon, maturity_date as maturity, issue_date, interest_accrual_date, currency_code, country_code, null as classification_1, null as classification_2, null as classification_3, first_coupon_date, coupon_frequency_code as coupon_freq, inflation_linked_flag as inflation_linked, null as is_green, cppib_sec_id
            from asset.asset_bond_universe where ticker<>'WIT' and ticker<>'CMBR' and issuer_name not like 'WI%' and sub_type='GOVERNMENT' and cppib_sec_id is not null and maturity_date is not null and issue_date is not null  and delete_date is null

