/* cppi::59d931a89b6337968aa05a06c86ac5ca53a19514f4dd1e1557979018f309e673 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-30' and end_date = '2025-05-30')
and start_date = '2025-05-30' and end_date = '2025-05-30'

/* cppi::4b848df6e81adea8ace9f143668abab564f31ca9fe027f7091340180e366f1e9 */
SELECT COUNT(*) FROM (SELECT * FROM (
select business_date, cppib_sec_id AS cppib_id,  from_currency_code AS from_currency, 
to_currency_code AS to_currency, type AS instrument_type, sub_type AS instrument_sub_type,
bid_value, askvalue AS ask_value, mid_value AS mid_value, business_date AS rate_date,
price_source_code AS price_source from market.cppib_rates
where business_date = date('2025-06-24') AND "type" = 'CURRENCY' AND sub_type = 'CROSS_RATE' AND price_source_code = 'WM Company'
) z_q WHERE from_currency IN ('CAD')
) dbvrcnt

